//! A macro's positions: where both fighters were on each recorded frame, for the clip editor's scrub. They live in a
//! small binary file beside the macro, `<id>.pos`, so the macro's own file is what it always was and playback never
//! reads them (operator 2026-11-26 03:06:35Z).
//!
//! ```text
//! 0   4  magic "TRPS"            12  4  the macro's input count
//! 4   2  format version, 1       16  8  FNV-1a 64 of the macro's id
//! 6   1  fighters, 2             24  8  FNV-1a 64 of the macro's inputs
//! 7   1  bytes per row, 36       32  1  source: 1 recorded with the take, 2 generated by a playback
//! 8   4  frames in this file     33  7  zero
//!                                40  …  per frame: the recorded fighter's row, then the other fighter's
//! ```
//!
//! A row is the state a match capture keeps per frame (`ReplayFrame` without its input), little-endian: kind `i32`,
//! costume `u32`, facing `f32`, situation `i32`, status `i32`, speed x and y `f32`, x and y `f32`. A fighter that
//! is not there has kind -1. The file is used only when every header field, its length and its binding fit the loaded
//! macro; anything else is no positions. It is written and read 600 frames at a time, with no serde.
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

use super::{InputFrame, ReplayFrame, StartState};

const MAGIC: [u8; 4] = *b"TRPS";
const VERSION: u16 = 1;
const FIGHTERS: u8 = 2;
const ROW: usize = 36;
const HEADER: usize = 40;
const FRAME: usize = FIGHTERS as usize * ROW;
const CHUNK_FRAMES: usize = 600;
const FNV_START: u64 = 0xcbf2_9ce4_8422_2325;

fn fnv(hash: u64, bytes: &[u8]) -> u64 {
    bytes.iter().fold(hash, |hash, byte| (hash ^ u64::from(*byte)).wrapping_mul(0x100_0000_01b3))
}

/// The positions file of the macro `id` in `dir`.
pub fn path(dir: &Path, id: &str) -> PathBuf {
    dir.join(format!("{id}.pos"))
}

/// Where a positions file came from: a take's own recording, or a playback of a macro that had none.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Source {
    Recorded = 1,
    Generated = 2,
}

/// What ties a positions file to its macro: the id it is stored under and the inputs it was recorded with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Binding {
    id: u64,
    inputs: u32,
    hash: u64,
}

impl Binding {
    fn of(id: &str, inputs: &[InputFrame]) -> Self {
        let hash = inputs.iter().fold(FNV_START, |hash, frame| {
            fnv(fnv(hash, &frame.buttons.to_le_bytes()), &[frame.lstick_x as u8, frame.lstick_y as u8, frame.rstick_x as u8, frame.rstick_y as u8])
        });
        Self { id: fnv(FNV_START, id.as_bytes()), inputs: inputs.len() as u32, hash }
    }
}

fn header(binding: Binding, frames: u32, source: Source) -> [u8; HEADER] {
    let mut out = [0u8; HEADER];
    out[..4].copy_from_slice(&MAGIC);
    out[4..6].copy_from_slice(&VERSION.to_le_bytes());
    out[6] = FIGHTERS;
    out[7] = ROW as u8;
    out[8..12].copy_from_slice(&frames.to_le_bytes());
    out[12..16].copy_from_slice(&binding.inputs.to_le_bytes());
    out[16..24].copy_from_slice(&binding.id.to_le_bytes());
    out[24..32].copy_from_slice(&binding.hash.to_le_bytes());
    out[32] = source as u8;
    out
}

fn word(bytes: &[u8], at: usize) -> u32 {
    u32::from_le_bytes([bytes[at], bytes[at + 1], bytes[at + 2], bytes[at + 3]])
}

/// The binding, the frame count and the source of a header this build reads.
fn parse(head: &[u8; HEADER]) -> Option<(Binding, usize, Source)> {
    if head[..4] != MAGIC || head[4..6] != VERSION.to_le_bytes() || head[6] != FIGHTERS || usize::from(head[7]) != ROW {
        return None;
    }
    let long = |at: usize| u64::from(word(head, at)) | u64::from(word(head, at + 4)) << 32;
    let source = match head[32] {
        1 => Source::Recorded,
        2 => Source::Generated,
        _ => return None,
    };
    Some((Binding { id: long(16), inputs: word(head, 12), hash: long(24) }, word(head, 8) as usize, source))
}

fn put_row(out: &mut [u8], frame: &ReplayFrame) {
    let start = frame.start;
    let words = [start.fighter_kind as u32, start.costume, start.facing.to_bits(), start.situation as u32, start.status as u32,
        start.speed_x.to_bits(), start.speed_y.to_bits(), frame.x.to_bits(), frame.y.to_bits()];
    for (cell, word) in out.as_chunks_mut::<4>().0.iter_mut().zip(words) {
        *cell = word.to_le_bytes();
    }
}

fn get_row(bytes: &[u8]) -> Option<ReplayFrame> {
    let float = |at: usize| Some(f32::from_bits(word(bytes, at))).filter(|value| value.is_finite());
    Some(ReplayFrame {
        input: InputFrame::default(),
        start: StartState { fighter_kind: word(bytes, 0) as i32, costume: word(bytes, 4), facing: float(8)?, situation: word(bytes, 12) as i32,
            status: word(bytes, 16) as i32, speed_x: float(20)?, speed_y: float(24)? },
        x: float(28)?,
        y: float(32)?,
    })
}

/// The header of the file there, when it is one this build reads, binds `inputs` under `id`, and has the length its
/// frame count says.
fn bound(file: &mut fs::File, id: &str, inputs: &[InputFrame]) -> Option<(usize, Source)> {
    let len = file.metadata().ok()?.len();
    let mut head = [0u8; HEADER];
    file.read_exact(&mut head).ok()?;
    let (binding, frames, source) = parse(&head)?;
    (binding == Binding::of(id, inputs) && frames <= inputs.len() && len == (HEADER + frames * FRAME) as u64).then_some((frames, source))
}

/// Whether the positions file of `id` is there and binds these inputs. Only its header is read.
pub fn binds(dir: &Path, id: &str, inputs: &[InputFrame]) -> bool {
    fs::File::open(path(dir, id)).ok().and_then(|mut file| bound(&mut file, id, inputs)).is_some()
}

/// Write the positions of the macro `id`, whose inputs are `inputs`: to `<id>.pos.tmp`, synced, then put in place.
/// Entries past the inputs are left out.
pub fn write(dir: &Path, id: &str, inputs: &[InputFrame], track: &[[ReplayFrame; 2]], source: Source) -> io::Result<()> {
    #[cfg(test)]
    if FAIL_WRITE.with(|fail| fail.get()) {
        return Err(io::Error::from(io::ErrorKind::Interrupted));
    }
    let track = &track[..track.len().min(inputs.len())];
    crate::model::store::replace_with(&path(dir, id), |tmp| {
        let mut file = fs::File::create(tmp)?;
        file.write_all(&header(Binding::of(id, inputs), track.len() as u32, source))?;
        let mut buffer = vec![0u8; CHUNK_FRAMES.min(track.len()) * FRAME];
        for chunk in track.chunks(CHUNK_FRAMES) {
            for (pair, out) in chunk.iter().zip(buffer.as_chunks_mut::<FRAME>().0) {
                put_row(&mut out[..ROW], &pair[0]);
                put_row(&mut out[ROW..], &pair[1]);
            }
            file.write_all(&buffer[..chunk.len() * FRAME])?;
        }
        file.sync_all()
    })
}

/// The positions of the macro `id`, whose inputs are `inputs`; none when the file is missing, is not one this build
/// reads, or does not bind this macro. A file with no rows is an empty track, not a missing one.
pub fn read(dir: &Path, id: &str, inputs: &[InputFrame]) -> Option<Vec<[ReplayFrame; 2]>> {
    #[cfg(test)]
    READS.with(|reads| reads.set(reads.get() + 1));
    let mut file = fs::File::open(path(dir, id)).ok()?;
    let (frames, _) = bound(&mut file, id, inputs)?;
    let mut track = Vec::new();
    track.try_reserve_exact(frames).ok()?;
    let mut buffer = vec![0u8; CHUNK_FRAMES.min(frames) * FRAME];
    while track.len() < frames {
        let count = (frames - track.len()).min(CHUNK_FRAMES);
        file.read_exact(&mut buffer[..count * FRAME]).ok()?;
        for bytes in buffer[..count * FRAME].as_chunks::<FRAME>().0 {
            track.push([get_row(&bytes[..ROW])?, get_row(&bytes[ROW..])?]);
        }
    }
    Some(track)
}

/// Where the positions file of `id` came from, when it binds these inputs. Only its header is read.
pub fn source(dir: &Path, id: &str, inputs: &[InputFrame]) -> Option<Source> {
    fs::File::open(path(dir, id)).ok().and_then(|mut file| bound(&mut file, id, inputs)).map(|(_, source)| source)
}

/// Remove the positions file of `id`, and its unfinished write; a missing file is fine. The folder is synced where
/// the system has that, so the removal is on the card before a new macro is written under the id.
pub fn remove(dir: &Path, id: &str) {
    let file = path(dir, id);
    let _ = fs::remove_file(crate::model::store::with_suffix(&file, ".tmp"));
    if unlink(&file).is_ok() {
        let _ = sync_folder(dir);
    }
}

fn unlink(path: &Path) -> io::Result<()> {
    #[cfg(test)]
    if FAULT.with(|fault| fault.get() == Some("unlink")) { return Err(io::ErrorKind::PermissionDenied.into()); }
    fs::remove_file(path)
}

fn sync_folder(dir: &Path) -> io::Result<()> {
    #[cfg(test)]
    if FAULT.with(|fault| fault.get() == Some("sync")) { return Err(io::Error::other("injected directory sync failure")); }
    fs::File::open(dir)?.sync_all()
}

#[cfg(test)]
thread_local! {
    static READS: core::cell::Cell<usize> = const { core::cell::Cell::new(0) };
    static FAIL_WRITE: core::cell::Cell<bool> = const { core::cell::Cell::new(false) };
    static FAULT: core::cell::Cell<Option<&'static str>> = const { core::cell::Cell::new(None) };
}

/// Positions files opened for reading by this thread (tests: playback and the list open none).
#[cfg(test)]
pub fn reads() -> usize {
    READS.with(|reads| reads.get())
}

/// Make this thread's next positions writes fail (tests: a save interrupted after the macro is in place).
#[cfg(test)]
pub fn fail_writes(fail: bool) {
    FAIL_WRITE.with(|cell| cell.set(fail));
}

#[cfg(test)]
mod tests {
    lib_unit_tests! {
    use super::*;
    use crate::engine::macros::{Library, MacroRecording};
    use std::sync::atomic::{AtomicUsize, Ordering};

    static NEXT: AtomicUsize = AtomicUsize::new(0);

    fn scratch() -> PathBuf {
        let dir = std::env::temp_dir().join(format!("tr-positions-{}-{}", std::process::id(), NEXT.fetch_add(1, Ordering::Relaxed)));
        fs::create_dir(&dir).unwrap();
        dir
    }

    fn inputs(count: u32) -> Vec<InputFrame> {
        (0..count).map(|i| InputFrame { buttons: i + 1, lstick_x: (i % 100) as i8, ..InputFrame::default() }).collect()
    }

    /// The recorded fighter walks right and up; the other one stands to its left facing it.
    fn pair(i: u32) -> [ReplayFrame; 2] {
        let i = i as f32;
        [ReplayFrame { input: InputFrame::default(), start: StartState { status: 14, speed_x: 0.5, ..StartState::neutral(18, 3, -1.0) }, x: 20.0 + 3.0 * i, y: i },
            ReplayFrame { input: InputFrame::default(), start: StartState { situation: 2, speed_y: -1.25, ..StartState::neutral(74, 0, 1.0) }, x: -40.0, y: 7.5 }]
    }

    fn track(frames: u32) -> Vec<[ReplayFrame; 2]> {
        (0..frames).map(pair).collect()
    }

    fn recording(name: &str, frames: u32, tracked: bool) -> MacroRecording {
        let mut recording = MacroRecording::new(name, "13.0.5", StartState::neutral(18, 0, 1.0), inputs(frames)).unwrap();
        if tracked {
            recording.set_track(Some(track(frames)));
        }
        recording
    }

    #[test]
    fn the_file_has_the_published_layout() {
        let dir = scratch();
        let inputs = inputs(700);
        write(&dir, "walk", &inputs, &track(650), Source::Recorded).unwrap();
        let bytes = fs::read(path(&dir, "walk")).unwrap();
        assert_eq!(path(&dir, "walk"), dir.join("walk.pos"));
        assert_eq!(bytes.len(), 40 + 72 * 650);
        assert_eq!((bytes[32], &bytes[33..40]), (1, &[0u8; 7][..]), "the source, then padding");
        assert_eq!(&bytes[..4], b"TRPS");
        assert_eq!((bytes[4], bytes[5], bytes[6], bytes[7]), (1, 0, 2, 36));
        assert_eq!((word(&bytes, 8), word(&bytes, 12)), (650, 700));
        let id = b"walk".iter().fold(0xcbf2_9ce4_8422_2325u64, |hash, byte| (hash ^ u64::from(*byte)).wrapping_mul(0x100_0000_01b3));
        assert_eq!(bytes[16..24], id.to_le_bytes());
        // The input hash is over each frame's buttons, little-endian, then its four stick bytes.
        let hash = inputs.iter().flat_map(|frame| frame.buttons.to_le_bytes().into_iter().chain([frame.lstick_x as u8, frame.lstick_y as u8, frame.rstick_x as u8, frame.rstick_y as u8]))
            .fold(0xcbf2_9ce4_8422_2325u64, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x100_0000_01b3));
        assert_eq!(bytes[24..32], hash.to_le_bytes());
        // Frame 2's rows: the recorded fighter's nine words, then the other fighter's.
        let row = |at: usize| (0..9).map(|cell| word(&bytes, 40 + 72 * 2 + at + 4 * cell)).collect::<Vec<_>>();
        assert_eq!(row(0), [18, 3, (-1.0f32).to_bits(), 0, 14, 0.5f32.to_bits(), 0, 26.0f32.to_bits(), 2.0f32.to_bits()]);
        assert_eq!(row(36), [74, 0, 1.0f32.to_bits(), 2, 0, 0, (-1.25f32).to_bits(), (-40.0f32).to_bits(), 7.5f32.to_bits()]);
        assert!(!dir.join("walk.pos.tmp").exists(), "the unfinished name is gone");
        // More than one chunk reads back whole; entries past the inputs are left out.
        assert_eq!(read(&dir, "walk", &inputs), Some(track(650)));
        assert_eq!(source(&dir, "walk", &inputs), Some(Source::Recorded));
        // A file made by a playback says so, and reads the same way.
        write(&dir, "walk", &inputs, &track(650), Source::Generated).unwrap();
        assert_eq!((source(&dir, "walk", &inputs), read(&dir, "walk", &inputs)), (Some(Source::Generated), Some(track(650))));
        assert_eq!(source(&dir, "walk", &inputs[..5]), None, "only for the macro it binds");
        write(&dir, "walk", &inputs[..10], &track(650), Source::Recorded).unwrap();
        assert_eq!(read(&dir, "walk", &inputs[..10]), Some(track(10)));
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn only_a_file_that_binds_its_macro_gives_positions() {
        let dir = scratch();
        let inputs = inputs(12);
        assert_eq!(read(&dir, "take", &inputs), None, "a missing file");
        assert!(!binds(&dir, "take", &inputs));
        // No rows is an empty track (positions that ran out at once), not a missing file.
        write(&dir, "take", &inputs, &[], Source::Recorded).unwrap();
        assert_eq!(read(&dir, "take", &inputs), Some(Vec::new()));
        // A prefix shorter than the inputs is whole.
        write(&dir, "take", &inputs, &track(8), Source::Recorded).unwrap();
        assert_eq!(read(&dir, "take", &inputs), Some(track(8)));
        assert!(binds(&dir, "take", &inputs));
        let good = fs::read(path(&dir, "take")).unwrap();
        type Edit = fn(&mut Vec<u8>);
        let broken: [(&str, Edit); 10] = [
            ("a source this build does not know", |bytes| bytes[32] = 3),
            ("the magic", |bytes| bytes[0] = b'X'),
            ("a later format version", |bytes| bytes[4] = 2),
            ("one fighter", |bytes| bytes[6] = 1),
            ("another row size", |bytes| bytes[7] = 40),
            ("a partial last row", |bytes| { bytes.pop(); }),
            ("bytes after the last row", |bytes| bytes.push(0)),
            ("more frames than the file holds", |bytes| bytes[8] = 9),
            ("more frames than the macro has inputs", |bytes| { bytes[8] = 13; bytes.extend([0; 72 * 5]); }),
            ("a number that is not finite", |bytes| bytes[40 + 28..40 + 32].copy_from_slice(&f32::NAN.to_le_bytes())),
        ];
        for (what, edit) in broken {
            let mut bytes = good.clone();
            edit(&mut bytes);
            fs::write(path(&dir, "take"), bytes).unwrap();
            assert_eq!(read(&dir, "take", &inputs), None, "{what}");
        }
        fs::write(path(&dir, "take"), &good).unwrap();
        // Another macro's inputs, a different count, the same file under another id: none of them binds.
        let mut other = inputs.clone();
        other[5].lstick_y = 1;
        assert_eq!(read(&dir, "take", &other), None, "one input differs");
        assert_eq!(read(&dir, "take", &inputs[..11]), None, "another input count");
        fs::copy(path(&dir, "take"), path(&dir, "copy")).unwrap();
        assert_eq!(read(&dir, "copy", &inputs), None, "copied under another id");
        assert!(!binds(&dir, "copy", &inputs) && !binds(&dir, "take", &other));
        assert_eq!(read(&dir, "take", &inputs), Some(track(8)));
        remove(&dir, "take");
        remove(&dir, "take");
        assert!(!path(&dir, "take").exists());
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn an_earlier_takes_file_under_the_same_id_does_not_bind() {
        // tr-primary-2 2026-11-26 03:10:37Z: the macro under an id is replaced by one with other inputs.
        let dir = scratch();
        let (first, second) = (inputs(20), (0..20).map(|i| InputFrame { buttons: 500 + i, ..InputFrame::default() }).collect::<Vec<_>>());
        write(&dir, "take", &first, &track(20), Source::Recorded).unwrap();
        assert!(!binds(&dir, "take", &second));
        assert_eq!((read(&dir, "take", &second), source(&dir, "take", &second)), (None, None));
        // Through the library: the earlier take's file is gone once the new macro is in place, and nothing shows.
        let library = Library::new(&dir);
        let id = library.save_new(&recording("Take", 20, true)).unwrap();
        let mut other = recording("Take", 20, false);
        other.frames = second;
        library.overwrite(&id, &other).unwrap();
        assert!(!path(&dir, &id).exists() && library.load_edited(&id).unwrap().track.is_none());
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn the_macro_file_is_unchanged_and_the_library_keeps_the_positions_beside_it() {
        let dir = scratch();
        let library = Library::new(&dir);
        // The macro's own file is the same bytes with and without positions, in the format older builds read.
        let plain = recording("Walk", 20, false);
        let tracked = recording("Walk", 20, true);
        let json = serde_json::to_string(&tracked).unwrap();
        assert_eq!(json, serde_json::to_string(&plain).unwrap());
        assert!(json.contains("\"schema_version\":1") && !json.contains("track"), "{json}");
        let id = library.save_new(&tracked).unwrap();
        assert_eq!(fs::read_to_string(dir.join(format!("{id}.json"))).unwrap(), json);
        assert!(path(&dir, &id).is_file(), "Record, Crop and a saved capture write the positions after the macro");
        // The list shows one macro; playback's load and the list open no positions file.
        let before = reads();
        let listing = library.list().unwrap();
        assert_eq!((listing.entries.len(), listing.skipped.len()), (1, 0));
        let played = library.load(&id).unwrap();
        assert_eq!((played.track.is_none(), played.frames.len(), reads()), (true, 20, before));
        // The clip editor's load reads them.
        assert_eq!(library.load_edited(&id).unwrap().track, Some(track(20)));
        assert_eq!(reads(), before + 1);
        // A macro saved without positions has none, also when a file of an earlier macro is left under its id.
        fs::copy(path(&dir, &id), dir.join("orphan.pos")).unwrap();
        let old = library.save_new(&plain).unwrap();
        assert!(!path(&dir, &old).exists() && library.load_edited(&old).unwrap().track.is_none());
        // Delete removes both files.
        library.delete(&id).unwrap();
        assert!(!path(&dir, &id).exists() && !dir.join(format!("{id}.json")).exists());
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn a_failed_sidecar_invalidation_cannot_commit_the_replacement_macro() {
        for fault in ["unlink", "sync"] {
            let dir = scratch();
            let library = Library::new(&dir);
            let id = library.save_new(&recording("Old", 3, true)).unwrap();
            let mut next = recording("Replacement", 3, false);
            next.set_track(Some(vec![pair(99); 3]));
            FAULT.with(|cell| cell.set(Some(fault)));
            fail_writes(true);
            let result = library.overwrite(&id, &next);
            let retry = library.overwrite(&id, &next);
            fail_writes(false);
            FAULT.with(|cell| cell.set(None));
            let reopened = library.load_edited(&id).unwrap();
            assert!(result.is_err(), "{fault} failed but overwrite reported success; macro={}", reopened.name);
            assert!(retry.is_err(), "a retry must not bypass an outstanding {fault} failure");
            assert_eq!(reopened.name, "Old");
            assert_eq!(reopened.track, (fault == "unlink").then(|| track(3)));
            library.overwrite(&id, &next).unwrap();
            assert_eq!(library.load_edited(&id).unwrap(), next);
            fs::remove_dir_all(dir).unwrap();
        }
    }

    #[test]
    fn an_overwrite_keeps_the_same_takes_positions_and_never_shows_another_takes() {
        let dir = scratch();
        let library = Library::new(&dir);
        let id = library.save_new(&recording("Take", 20, true)).unwrap();
        // The same take written again without its track in memory (a rename, a placement, Trim): the positions stay.
        let mut renamed = library.load(&id).unwrap();
        renamed.name = "Renamed".into();
        library.overwrite(&id, &renamed).unwrap();
        assert_eq!(library.load_edited(&id).unwrap().track, Some(track(20)));
        // Other inputs under the id, with no positions: the old ones go.
        let mut cut = renamed.clone();
        cut.keep(0..10);
        library.overwrite(&id, &cut).unwrap();
        assert!(!path(&dir, &id).exists() && library.load_edited(&id).unwrap().track.is_none());
        // A new take with the SAME inputs and other positions, and the save is interrupted after the macro is in
        // place: no positions show, never the earlier take's (tr-primary-2 2026-11-26 03:12:06Z).
        library.overwrite(&id, &recording("Take", 20, true)).unwrap();
        assert!(path(&dir, &id).is_file());
        let mut again = recording("Take", 20, false);
        again.set_track(Some((0..20).map(|i| pair(i + 100)).collect()));
        fail_writes(true);
        library.overwrite(&id, &again).unwrap();
        fail_writes(false);
        assert_eq!(library.load(&id).unwrap().name, "Take", "the macro itself is saved");
        assert!(!path(&dir, &id).exists() && library.load_edited(&id).unwrap().track.is_none());
        // The same save, not interrupted, has the new take's positions.
        library.overwrite(&id, &again).unwrap();
        assert_eq!(library.load_edited(&id).unwrap().track, Some((0..20).map(|i| pair(i + 100)).collect()));
        fs::remove_dir_all(dir).unwrap();
    }
    }
}
